#!/usr/bin/env node

/**
 * `.cursorrules` is generated by `mbe sync-rules` (tools/cli/src/commands/
 * sync-rules.ts): a managed header plus AGENTS.md verbatim. Nothing ran the
 * generator, so Cursor kept reading a long-stale copy (#6779). This check
 * fails when the committed file differs from what the generator would write.
 *
 * GEMINI.md is deliberately not covered: sync-rules only injects an AGENTS.md
 * link when the file lacks one, and GEMINI.md already links it, so the
 * generator never rewrites it and there is no generated content to drift.
 *
 * Fix: pnpm build --filter @mbe/cli... && node tools/cli/dist/index.js sync-rules
 *
 * Usage: node scripts/check-cursorrules-drift.mjs
 * Exit code: 0 if in sync, 1 otherwise
 */

import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { runCheck } from "./lib/fitness-check.mjs";

const DEFAULT_ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");

// Mirrors MANAGED_HEADER and the template in tools/cli/src/commands/sync-rules.ts.
export const expectedCursorRules = (agentsContent) =>
  `<!-- @mbe-managed - DO NOT EDIT MANUALLY -->\n# Cursor Rules - mattbutlerengineering\n\n${agentsContent}`;

/** Pure check — returns [".cursorrules"] when it differs from the generator output. */
export function findCursorRulesDrift(root = DEFAULT_ROOT) {
  try {
    const agents = readFileSync(join(root, "AGENTS.md"), "utf-8");
    const current = readFileSync(join(root, ".cursorrules"), "utf-8");
    return current === expectedCursorRules(agents) ? [] : [".cursorrules"];
  } catch {
    return [".cursorrules"];
  }
}

const isMain = process.argv[1] && process.argv[1].endsWith("check-cursorrules-drift.mjs");

if (isMain) {
  const findings = findCursorRulesDrift();

  const exitCode = runCheck({
    name: "Cursor rules drift",
    findings,
    formatFinding: (file) => file,
    passMessage: "PASS: .cursorrules matches the managed header + AGENTS.md.",
    failMessage: [
      "FAIL: .cursorrules differs from `mbe sync-rules` output (header + AGENTS.md). Regenerate it:",
      "  pnpm build --filter @mbe/cli... && node tools/cli/dist/index.js sync-rules",
      "Drifted file(s):",
    ].join("\n"),
  });
  process.exit(exitCode);
}
